# --- Row-level security and grants (ARCHITECTURE.md §6, DATABASE.md §3) -------------
# Policies apply to app_runtime only; app_platform has BYPASSRLS and app_owner owns the tables.

TENANT_TABLES = (
    "tenant_settings",
    "tenant_onboarding",
    "tenant_memberships",
    "membership_roles",
    "usage_records",
    "notifications",
    "idempotency_keys",
    "document_sequences",
)
# Tenants can read their own subscription data; only the platform writes it.
TENANT_READ_ONLY_TABLES = ("subscriptions", "subscription_history", "subscription_payments")
# Shared reference data: readable, never written by the runtime role.
RUNTIME_READ_ONLY_TABLES = ("plans", "plan_prices", "plan_features", "roles", "permissions", "role_permissions")


def _enable_rls(table: str) -> None:
    op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
    op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")


def _apply_security() -> None:
    for table in TENANT_TABLES:
        _enable_rls(table)
        op.execute(
            f"CREATE POLICY tenant_isolation ON {table} FOR ALL TO app_runtime "
            "USING (tenant_id = app_current_tenant()) WITH CHECK (tenant_id = app_current_tenant())"
        )

    for table in TENANT_READ_ONLY_TABLES:
        _enable_rls(table)
        op.execute(
            f"CREATE POLICY tenant_read ON {table} FOR SELECT TO app_runtime USING (tenant_id = app_current_tenant())"
        )
        op.execute(f"REVOKE INSERT, UPDATE, DELETE ON {table} FROM app_runtime")

    # A tenant sees only its own tenant row and cannot modify it directly.
    _enable_rls("tenants")
    op.execute("CREATE POLICY tenant_self ON tenants FOR SELECT TO app_runtime USING (id = app_current_tenant())")
    op.execute(
        "CREATE POLICY tenant_self_update ON tenants FOR UPDATE TO app_runtime "
        "USING (id = app_current_tenant()) WITH CHECK (id = app_current_tenant())"
    )
    # Owners may edit business details; status, slug, numbering etc. stay platform-managed.
    op.execute("REVOKE INSERT, UPDATE, DELETE ON tenants FROM app_runtime")
    op.execute(
        "GRANT UPDATE (business_name, legal_name, email, phone, address, tax_number, vat_registered, "
        "logo_object_id, updated_at) ON tenants TO app_runtime"
    )

    # Files: tenant-owned rows only; platform files (tenant_id NULL) are platform-only.
    _enable_rls("stored_objects")
    op.execute(
        "CREATE POLICY tenant_isolation ON stored_objects FOR ALL TO app_runtime "
        "USING (tenant_id = app_current_tenant()) WITH CHECK (tenant_id = app_current_tenant())"
    )

    # Audit log: append-only for every application role. Tenants read their own rows;
    # pre-tenant events (e.g. failed login) are written with tenant_id NULL.
    _enable_rls("audit_logs")
    op.execute(
        "CREATE POLICY tenant_read ON audit_logs FOR SELECT TO app_runtime USING (tenant_id = app_current_tenant())"
    )
    op.execute(
        "CREATE POLICY tenant_append ON audit_logs FOR INSERT TO app_runtime "
        "WITH CHECK (tenant_id IS NULL OR tenant_id = app_current_tenant())"
    )
    op.execute("REVOKE UPDATE, DELETE, TRUNCATE ON audit_logs FROM app_runtime, app_platform")

    for table in RUNTIME_READ_ONLY_TABLES:
        op.execute(f"REVOKE INSERT, UPDATE, DELETE ON {table} FROM app_runtime")

    # Our staff accounts are invisible to the tenant runtime role.
    op.execute("REVOKE ALL ON platform_users FROM app_runtime")
